import sys
from datetime import date, timedelta, datetime

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"

def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day_str, start_str, end_str = parts[1:]
            day = date.fromisoformat(day_str)
            start = datetime.strptime(start_str, "%H:%M").time()
            end = datetime.strptime(end_str, "%H:%M").time()
            busy.setdefault((who, day), []).append((start, end))
        else:
            key = parts[0]
            settings[key] = parts[1:]
    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    open_at = datetime.min.time()
    close_at = datetime.max.time()
    need = int(settings["duration"][0])
    buffer = int(settings["buffer"][0]) if "buffer" in settings else 0
    day = first
    while day <= last:
        taken = []
        for who, dates in busy.items():
            for date_str in dates:
                day = date.fromisoformat(date_str)
                for start, end in busy[(who, day)]:
                    taken.append((start, end))
        slots = []
        cursor = open_at
        for start, end in taken:
            if start - cursor >= need + buffer:
                slots.append(f"{clock(cursor)}-{clock(start)}")
            cursor = end
        if close_at - cursor >= need + buffer:
            slots.append(f"{clock(cursor)}-{clock(close_at)}")
        free_slots = []
        current_slot_start = open_at
        for start, end in taken:
            if start - current_slot_start >= need:
                free_slots.append(f"{clock(current_slot_start)}-{clock(start)}")
                current_slot_start = start
        if close_at - current_slot_start >= need:
            free_slots.append(f"{clock(current_slot_start)}-{clock(close_at)}")
        print(day.isoformat(), " ".join(free_slots) or "none")
        day += timedelta(days=1)


if __name__ == "__main__":
    main()
